/// TeachO 86 Master Courses Catalog for Flutter
/// Autogenerated and mapped across all 10 academic and career categories.

class TeachoSubject {
  final String name;
  final String icon;
  final String? code;

  const TeachoSubject({
    required this.name,
    required this.icon,
    this.code,
  });

  Map<String, dynamic> toMap() => {
    'name': name,
    'icon': icon,
    if (code != null) 'code': code,
  };
}

class TeachoTask {
  final String id;
  final String title;
  final String duration;
  final String type;
  final String icon;
  final String rawSubject;
  final String rawTopic;

  const TeachoTask({
    required this.id,
    required this.title,
    required this.duration,
    required this.type,
    required this.icon,
    required this.rawSubject,
    required this.rawTopic,
  });
}

class TeachoCourse {
  final String id;
  final String title;
  final String short;
  final String subtitle;
  final String category;
  final String gradeLevel;
  final String board;
  final String medium;
  final String badge;
  final String icon;
  final int totalDays;
  final String phaseTitle;
  final String milestoneTitle;
  final List<TeachoSubject> subjects;
  final List<TeachoTask> tasks;

  const TeachoCourse({
    required this.id,
    required this.title,
    required this.short,
    required this.subtitle,
    required this.category,
    required this.gradeLevel,
    required this.board,
    required this.medium,
    required this.badge,
    required this.icon,
    required this.totalDays,
    required this.phaseTitle,
    required this.milestoneTitle,
    required this.subjects,
    required this.tasks,
  });
}

